CREATE MATERIALIZED VIEW non_leaf_847 AS
SELECT ci.id AS ci_id, ci.person_id AS ci_person_id, ci.movie_id AS ci_movie_id, ci.person_role_id AS ci_person_role_id, ci.note AS ci_note, ci.nr_order AS ci_nr_order, ci.role_id AS ci_role_id, rt.id AS rt_id, rt.role AS rt_role, t.id AS t_id, t.title AS t_title, t.imdb_index AS t_imdb_index, t.kind_id AS t_kind_id, t.production_year AS t_production_year, t.imdb_id AS t_imdb_id, t.phonetic_code AS t_phonetic_code, t.episode_of_id AS t_episode_of_id, t.season_nr AS t_season_nr, t.episode_nr AS t_episode_nr, t.series_years AS t_series_years, t.md5sum AS t_md5sum, mi1.id AS mi1_id, mi1.movie_id AS mi1_movie_id, mi1.info_type_id AS mi1_info_type_id, mi1.info AS mi1_info, mi1.note AS mi1_note, mc.id AS mc_id, mc.movie_id AS mc_movie_id, mc.company_id AS mc_company_id, mc.company_type_id AS mc_company_type_id, mc.note AS mc_note, cn.id AS cn_id, cn.name AS cn_name, cn.country_code AS cn_country_code, cn.imdb_id AS cn_imdb_id, cn.name_pcode_nf AS cn_name_pcode_nf, cn.md5sum AS cn_md5sum
FROM cast_info AS ci, role_type AS rt, title AS t, movie_info AS mi1, movie_companies AS mc, company_name AS cn
WHERE ci.movie_id = t.id AND ci.role_id = rt.id AND rt.role IN ('actor', 'actress', 'costume designer', 'director', 'editor', 'guest', 'miscellaneous crew', 'producer') AND t.id = mc.movie_id AND t.production_year <= 2015 AND t.production_year >= 1875 AND mi1.movie_id = mc.movie_id AND mi1.info ~~* '%di%' AND mi1.info_type_id = 6 AND mc.company_id = cn.id AND cn.name ~~* '%col%';